146:                             }
147:                             else if(input_slpmsg.transactionType === SlpTransactionType.GENESIS || input_slpmsg.transactionType === SlpTransactionType.MINT) {
148:                                 if(txn.inputs[i].outputIndex === 1)
149:                                     tokenInQty = tokenInQty.plus(input_slpmsg.genesisOrMintQuantity)
150:                                     this.cachedValidations[txid].parents.push({txid: txn.inputs[i].prevTxId.toString('hex'), versionType: input_slpmsg.versionType, valid: null, inputQty: input_slpmsg.genesisOrMintQuantity })
151:                             }
152:                         }
153:                     } catch(_) {}
154:                 }
155:             }
156:             
157:             // Check token inputs are greater than token outputs (includes valid and invalid inputs)
158:             if(tokenOutQty.isGreaterThan(tokenInQty)) {
