164:         // Set validity validation-cache for parents, and handle MINT condition with no valid input
165:         let parentTxids = [...new Set(this.cachedValidations[txid].parents.map(p => p.txid))];
166:         for(let i = 0; i < parentTxids.length; i++) {
167:             let valid = await this.isValidSlpTxid(parentTxids[i])
168:             this.cachedValidations[txid].parents.filter(p => p.txid === parentTxids[i]).map(p => p.valid = valid);
169:             if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.MINT && !valid) {
170:                 this.cachedValidations[txid].invalidReason = "MINT transaction with invalid baton parent."
171:                 return this.cachedValidations[txid].validity = false;
172:             }
173:         }
174: 
175:         // Check valid inputs are greater than token outputs
176:         if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
177:             let validInputQty = this.cachedValidations[txid].parents.reduce((t, v) => { return v.valid ? t.plus(v.inputQty) : t }, new BigNumber(0));
178:             let tokenOutQty = slpmsg.sendOutputs.reduce((t,v)=>{ return t.plus(v) }, new BigNumber(0))
179:             if(tokenOutQty.isGreaterThan(validInputQty)) {
180:                 this.cachedValidations[txid].invalidReason = "Token outputs are greater than valid token inputs."
181:                 return this.cachedValidations[txid].validity = false;
182:             }
183:         }
