186:         if(this.cachedValidations[txid].parents.filter(p => p.valid).length > 0) {
187:             let validVersionType = this.cachedValidations[txid].parents.find(p => p.valid).versionType;
188:             if(this.cachedValidations[txid].details.versionType !== validVersionType) {
189:                 this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid parent."
190:                 return this.cachedValidations[txid].validity = false;
191:             }
192:         } 
193:         // For case with 0 token SEND with no valid parents, must check GENESIS validity / versionType.
194:         else if(this.cachedValidations[txid].details.transactionType === SlpTransactionType.SEND) {
195:             let slpmsg = this.cachedValidations[txid].details
196:             let valid = await this.isValidSlpTxid(slpmsg.tokenIdHex);
197:             if(valid) {
198:                 let genesisTxn: BitcoreTransaction = new bitcore.Transaction(this.cachedValidations[slpmsg.tokenIdHex].hex)
199:                 let genesisMsg = this.slp.parseSlpOutputScript(genesisTxn.outputs[0]._scriptBuffer)
200:                 if(genesisMsg.versionType !== slpmsg.versionType) {
201:                     this.cachedValidations[txid].invalidReason = "SLP version/type mismatch from valid GENESIS."
202:                     return this.cachedValidations[txid].validity = false;
203:                 }
204:             } else {
205:                 this.cachedValidations[txid].invalidReason = "SEND has 0 outputs, but has invalid token GENESIS."
206:                 return this.cachedValidations[txid].validity = false;
207:             }
208:         }
209: 
210:         return this.cachedValidations[txid].validity = true;
211:     }
