213:     async validateSlpTransactions(txids: string[]): Promise<string[]> {
214:         let res = [];
215:         for (let i = 0; i < txids.length; i++) {
216:             res.push((await this.isValidSlpTxid) ? txids[i] : '')
217:         }
218:         return res.filter((id: string) => id.length > 0);
219:     }
220: }

